axs[2].plot(a['t'],np.rad2deg(a['truth'][:,0]),'k',lw=2,label='Recorded');axs[2].set(title='Hood River tight-turn entry',xlabel='Seconds from 447 s',ylabel='Payload bank (deg)');axs[2].legend(fontsize=8)
